FormulaFieldDefinitions.FormulaFieldDefinition:
if (isnull({Product.Color}) and isnull({Product.Size})) then {Product.M_F}
else
if (isnull({Product.Size}) and isnull({Product.M_F})) then {Product.Color}
else
if (isnull({Product.Color}) and isnull({Product.M_F})) then {Product.Size}
else
if isnull({Product.Color}) then {Product.Size}+" / " + {Product.M_F}
else
if isnull({Product.Size}) then {Product.Color} +" / " + {Product.M_F}
else
if isnull({Product.M_F}) then {Product.Color} + " / " +{Product.Size}
else
if (isnull({Product.Color}) and isnull({Product.Size}) and isnull({Product.M_F})) then ""
else
{Product.Color} + " / " + {Product.Size} +" / " + {Product.M_F}

